export class ListNode {
  val: number;
  next: ListNode | null;
  constructor(val = 0, next: ListNode | null = null) {
    this.val = val;
    this.next = next;
  }
}

export function removeElements(
  head: ListNode | null,
  val: number,
): ListNode | null {
  const dummy = new ListNode(0);
  dummy.next = head;
  let curr: ListNode | null = dummy;
  while (curr!.next) {
    if (curr!.next.val === val) {
      curr!.next = curr!.next.next;
    } else {
      curr = curr!.next;
    }
  }
  return dummy.next;
}
